import React, { createContext, useState, useEffect } from "react";

export const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const storedToken = localStorage.getItem("token");
    const storedUser = localStorage.getItem("user");
    if (storedToken && storedUser) {
      setToken(storedToken);
      setUser(JSON.parse(storedUser));
    }
    setLoading(false);
  }, []);

  const login = async (username, password) => {
    const formData = new FormData();
    formData.append("username", username);
    formData.append("password", password);

    try {
      const response = await fetch("http://127.0.0.1:8000/api/auth/login", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "Login gagal");
      }

      const data = await response.json();
      localStorage.setItem("token", data.access_token);
      localStorage.setItem(
        "user",
        JSON.stringify({
          username: data.username,
          role: data.role,
          full_name: data.full_name,
        })
      );

      setToken(data.access_token);
      setUser({
        username: data.username,
        role: data.role,
        full_name: data.full_name,
      });

      return { success: true };
    } catch (error) {
      return { success: false, message: error.message };
    }
  };

  const logout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    setToken(null);
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, token, login, logout, loading }}>
      {children}
    </AuthContext.Provider>
  );
};

@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;500;600;700;800&display=swap');

:root {
  --bg-primary: #0b0f19;
  --bg-secondary: #131a26;
  --bg-card: rgba(26, 34, 50, 0.6);
  --bg-input: #1b2436;
  --border-color: rgba(255, 255, 255, 0.08);
  --border-glow: rgba(56, 189, 248, 0.15);

  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;

  --accent-blue: #38bdf8;
  --accent-blue-hover: #0ea5e9;
  --accent-purple: #a855f7;

  --success: #10b981;
  --success-bg: rgba(16, 185, 129, 0.1);
  --warning: #f59e0b;
  --warning-bg: rgba(245, 158, 11, 0.1);
  --danger: #ef4444;
  --danger-bg: rgba(239, 68, 68, 0.1);

  --font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --shadow-premium: 0 10px 30px -10px rgba(0, 0, 0, 0.5);
  --shadow-glow: 0 0 20px rgba(56, 189, 248, 0.15);

  --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --border-radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-family);
  min-height: 100vh;
  line-height: 1.5;
  overflow-x: hidden;
}

/* Glassmorphic Container & Card Styles */
.glass-panel {
  background: var(--bg-card);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius);
  box-shadow: var(--shadow-premium);
  padding: 24px;
  transition: var(--transition);
}

.glass-panel:hover {
  border-color: rgba(56, 189, 248, 0.25);
  box-shadow: var(--shadow-premium), 0 0 15px rgba(56, 189, 248, 0.05);
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

h1 {
  font-size: 2.2rem;
  background: linear-gradient(135deg, #ffffff 40%, var(--accent-blue) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

h2 {
  font-size: 1.6rem;
  margin-bottom: 16px;
}

p {
  color: var(--text-secondary);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 20px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: var(--transition);
  gap: 8px;
  text-decoration: none;
}

.btn-primary {
  background: linear-gradient(135deg, var(--accent-blue) 0%, #0369a1 100%);
  color: #0b0f19;
  box-shadow: 0 4px 14px rgba(56, 189, 248, 0.25);
}

.btn-primary:hover {
  background: linear-gradient(135deg, #7dd3fc 0%, var(--accent-blue-hover) 100%);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(56, 189, 248, 0.35);
}

.btn-secondary {
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-primary);
  border: 1px solid var(--border-color);
}

.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: var(--text-secondary);
}

.btn-danger {
  background: linear-gradient(135deg, var(--danger) 0%, #991b1b 100%);
  color: white;
  box-shadow: 0 4px 14px rgba(239, 68, 68, 0.2);
}

.btn-danger:hover {
  background: linear-gradient(135deg, #f87171 0%, var(--danger) 100%);
  transform: translateY(-2px);
}

.btn-success {
  background: linear-gradient(135deg, var(--success) 0%, #065f46 100%);
  color: #0b0f19;
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.2);
}

.btn-success:hover {
  background: linear-gradient(135deg, #34d399 0%, var(--success) 100%);
  transform: translateY(-2px);
}

.btn:active {
  transform: translateY(0);
}

/* Inputs & Form Elements */
.form-group {
  margin-bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.input-control {
  background-color: var(--bg-input);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 12px 16px;
  color: var(--text-primary);
  font-family: var(--font-family);
  font-size: 0.95rem;
  transition: var(--transition);
  outline: none;
  width: 100%;
}

.input-control:focus {
  border-color: var(--accent-blue);
  box-shadow: 0 0 10px rgba(56, 189, 248, 0.15);
  background-color: #1e293b;
}

/* Tables */
table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 10px;
}

th {
  background: rgba(255, 255, 255, 0.03);
  color: var(--text-secondary);
  font-weight: 600;
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 12px 16px;
  text-align: left;
  border-bottom: 1.5px solid var(--border-color);
}

td {
  padding: 12px 16px;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border-color);
  font-size: 0.95rem;
}

tr:hover td {
  background-color: rgba(255, 255, 255, 0.01);
}

/* Badges / Pill Tags */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge-sangat-baik {
  background: rgba(16, 185, 129, 0.15);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.badge-baik {
  background: rgba(14, 165, 233, 0.15);
  color: #38bdf8;
  border: 1px solid rgba(14, 165, 233, 0.3);
}

.badge-cukup {
  background: rgba(245, 158, 11, 0.15);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.badge-kurang {
  background: rgba(249, 115, 22, 0.15);
  color: #fb923c;
  border: 1px solid rgba(249, 115, 22, 0.3);
}

.badge-ditolak {
  background: rgba(239, 68, 68, 0.15);
  color: #f87171;
  border: 1px solid rgba(239, 68, 68, 0.3);
}

/* Warnings / Alerts */
.alert {
  padding: 16px;
  border-radius: 8px;
  margin-bottom: 20px;
  display: flex;
  gap: 12px;
  align-items: flex-start;
  font-size: 0.9rem;
}

.alert-danger {
  background-color: var(--danger-bg);
  color: #f87171;
  border: 1px solid rgba(239, 68, 68, 0.2);
}

.alert-warning {
  background-color: var(--warning-bg);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.2);
}

.alert-success {
  background-color: var(--success-bg);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.2);
}

/* Animations */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in {
  animation: fadeIn 0.4s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Sidebar & Layout Styles */
.layout-container {
  display: flex;
  min-height: 100vh;
}

.sidebar {
  width: 260px;
  background-color: var(--bg-secondary);
  border-right: 1px solid var(--border-color);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 30px;
}

.sidebar-brand {
  display: flex;
  align-items: center;
  gap: 10px;
}

.sidebar-brand h3 {
  font-size: 1.1rem;
  letter-spacing: 0.05em;
  background: linear-gradient(135deg, #fff 0%, var(--accent-blue) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.sidebar-menu {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sidebar-link {
  display: flex;
  align-items: center;
  padding: 12px 16px;
  border-radius: 8px;
  color: var(--text-secondary);
  text-decoration: none;
  font-weight: 500;
  transition: var(--transition);
  cursor: pointer;
  gap: 12px;
}

.sidebar-link:hover, .sidebar-link.active {
  color: var(--text-primary);
  background-color: rgba(56, 189, 248, 0.08);
  border-left: 3px solid var(--accent-blue);
}

.main-content {
  flex: 1;
  padding: 40px;
  overflow-y: auto;
}

/* Grid helper */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 20px;
}

/* Header bar */
.topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 30px;
  padding-bottom: 15px;
  border-bottom: 1px solid var(--border-color);
}

/* Side by Side layout for OCR edit */
.side-by-side {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
  min-height: 500px;
}

.pdf-viewer-sim {
  background-color: #0f172a;
  border: 1px dashed var(--border-color);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  flex-direction: column;
  padding: 40px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.ocr-editor-table {
  background-color: rgba(30, 41, 59, 0.4);
  border-radius: 8px;
  padding: 16px;
}

.score-dimension-card {
  padding: 16px;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background-color: rgba(255, 255, 255, 0.01);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.score-val {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--accent-blue);
}

import React, { useState, useContext } from "react";
import { AuthContext } from "../context/AuthContext";

const Login = () => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const { login } = useContext(AuthContext);

  const handleSubmit = async (e) => {
    if (e) e.preventDefault();
    setError("");
    setLoading(true);

    if (!username || !password) {
      setError("Username dan password harus diisi");
      setLoading(false);
      return;
    }

    const res = await login(username, password);
    setLoading(false);
    if (!res.success) {
      setError(res.message || "Login gagal, silakan coba lagi.");
    }
  };

  const handleQuickLogin = (roleUser, rolePass) => {
    setUsername(roleUser);
    setPassword(rolePass);
    // Submit using state in next tick or call login directly
    setTimeout(() => {
      const form = document.getElementById("login-form");
      if (form) {
        form.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
      }
    }, 100);
  };

  return (
    <div style={{
      display: "flex", 
      alignItems: "center", 
      justifyContent: "center", 
      minHeight: "100vh",
      background: "radial-gradient(circle at 10% 20%, rgba(4, 18, 38, 1) 0%, rgba(11, 15, 25, 1) 90%)",
      padding: "20px"
    }}>
      <div className="glass-panel fade-in" style={{ width: "100%", maxWidth: "450px", padding: "40px 30px" }}>
        <div style={{ textAlign: "center", marginBottom: "30px" }}>
          <h2 style={{ fontSize: "1.8rem", color: "var(--accent-blue)" }}>AI Underwriting</h2>
          <p style={{ fontSize: "0.9rem" }}>Sistem Skoring Surety Bond & KBG</p>
        </div>

        {error && (
          <div className="alert alert-danger" style={{ marginBottom: "20px" }}>
            <div>{error}</div>
          </div>
        )}

        <form id="login-form" onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="username">Username</label>
            <input
              id="username"
              type="text"
              className="input-control"
              placeholder="Masukkan username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
            />
          </div>

          <div className="form-group" style={{ marginBottom: "24px" }}>
            <label htmlFor="password">Password</label>
            <input
              id="password"
              type="password"
              className="input-control"
              placeholder="Masukkan password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>

          <button 
            type="submit" 
            className="btn btn-primary" 
            style={{ width: "100%", padding: "12px", fontSize: "1rem" }}
            disabled={loading}
          >
            {loading ? "Masuk..." : "Masuk ke Sistem"}
          </button>
        </form>

        <div style={{ marginTop: "30px", borderTop: "1px solid var(--border-color)", paddingTop: "20px" }}>
          <p style={{ fontSize: "0.8rem", color: "var(--text-muted)", marginBottom: "12px", textAlign: "center", fontWeight: "600" }}>
            AKSES CEPAT (SIMULASI RBAC)
          </p>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "10px" }}>
            <button 
              onClick={() => handleQuickLogin("marketing", "marketing123")}
              className="btn btn-secondary" 
              style={{ fontSize: "0.8rem", padding: "8px" }}
            >
              💼 Marketing
            </button>
            <button 
              onClick={() => handleQuickLogin("analis", "analis123")}
              className="btn btn-secondary" 
              style={{ fontSize: "0.8rem", padding: "8px" }}
            >
              🔍 Analis
            </button>
            <button 
              onClick={() => handleQuickLogin("komite", "komite123")}
              className="btn btn-secondary" 
              style={{ fontSize: "0.8rem", padding: "8px" }}
            >
              ⚖️ Komite Pemutus
            </button>
            <button 
              onClick={() => handleQuickLogin("admin", "admin123")}
              className="btn btn-secondary" 
              style={{ fontSize: "0.8rem", padding: "8px" }}
            >
              🛠️ Administrator
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect, useContext } from "react";
import { AuthContext } from "../context/AuthContext";

const CommonDashboard = ({ setActiveView }) => {
  const { user, token, logout } = useContext(AuthContext);
  const [prospects, setProspects] = useState([]);
  const [selectedProspect, setSelectedProspect] = useState(null);
  const [detailData, setDetailData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);

  // OCR Form States (Analis)
  const [ocrRows, setOcrRows] = useState([]);

  // Komite Decision States
  const [decisionAction, setDecisionAction] = useState("approved");
  const [decisionNotes, setDecisionNotes] = useState("");

  // Fetch Prospects
  const fetchProspects = async () => {
    setLoading(true);
    try {
      const response = await fetch("http://127.0.0.1:8000/api/prospects", {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (response.ok) {
        const data = await response.ok ? await response.json() : [];
        setProspects(data);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProspects();
  }, []);

  // Fetch Detail
  const fetchDetail = async (id) => {
    try {
      const response = await fetch(`http://127.0.0.1:8000/api/prospects/${id}`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (response.ok) {
        const data = await response.json();
        setDetailData(data);
        // Prepare OCR rows for editing
        if (data.financial_data) {
          setOcrRows(JSON.parse(JSON.stringify(data.financial_data))); // deep copy
        }
      }
    } catch (e) {
      console.error(e);
    }
  };

  const handleSelectProspect = (id) => {
    setSelectedProspect(id);
    fetchDetail(id);
  };

  const handleBackToList = () => {
    setSelectedProspect(null);
    setDetailData(null);
    fetchProspects();
  };

  // Upload Document (Marketing)
  const handleUpload = async (docId, file) => {
    if (!file) return;
    setActionLoading(true);
    const formData = new FormData();
    formData.append("doc_id", docId);
    formData.append("file", file);

    try {
      const response = await fetch(`http://127.0.0.1:8000/api/prospects/${selectedProspect}/upload-doc`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData
      });
      if (response.ok) {
        alert("Dokumen berhasil diunggah.");
        fetchDetail(selectedProspect);
      } else {
        const err = await response.json();
        alert("Error: " + err.detail);
      }
    } catch (e) {
      alert("Gagal mengunggah dokumen.");
    } finally {
      setActionLoading(false);
    }
  };

  // Bypass Manual for Blur Document (Analis / Marketing)
  const handleBypassBlur = async () => {
    if (!confirm("Bypass verifikasi kualitas dokumen secara manual?")) return;
    setActionLoading(true);
    try {
      const response = await fetch(`http://127.0.0.1:8000/api/prospects/${selectedProspect}/bypass-blur`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` }
      });
      if (response.ok) {
        alert("Pemeriksaan kualitas berhasil di-bypass.");
        fetchDetail(selectedProspect);
      }
    } catch (e) {
      alert("Gagal melakukan bypass.");
    } finally {
      setActionLoading(false);
    }
  };

  // OCR Table Edit Changes
  const handleOcrCellChange = (index, field, value) => {
    const updated = [...ocrRows];
    updated[index][field] = parseFloat(value) || 0.0;
    setOcrRows(updated);
  };

  // Save Verified OCR Data (Analis)
  const handleSaveOcr = async () => {
    setActionLoading(true);
    try {
      const response = await fetch(`http://127.0.0.1:8000/api/prospects/${selectedProspect}/verify-ocr`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify(ocrRows)
      });
      if (response.ok) {
        alert("Data keuangan berhasil diverifikasi & skoring diperbarui.");
        fetchDetail(selectedProspect);
      } else {
        alert("Gagal menyimpan data keuangan.");
      }
    } catch (e) {
      alert("Gagal mengirim data verifikasi.");
    } finally {
      setActionLoading(false);
    }
  };

  // Komite Decision
  const handleDecision = async (e) => {
    e.preventDefault();
    setActionLoading(true);
    const formData = new FormData();
    formData.append("action", decisionAction);
    formData.append("notes", decisionNotes);

    try {
      const response = await fetch(`http://127.0.0.1:8000/api/prospects/${selectedProspect}/decide`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData
      });
      if (response.ok) {
        alert(`Keputusan disimpan sebagai: ${decisionAction.toUpperCase()}`);
        fetchDetail(selectedProspect);
      } else {
        alert("Gagal menyimpan keputusan.");
      }
    } catch (e) {
      alert("Terjadi kesalahan.");
    } finally {
      setActionLoading(false);
    }
  };

  // Statistics KPI counts
  const stats = {
    total: prospects.length,
    approved: prospects.filter(p => p.status === "approved").length,
    rejected: prospects.filter(p => p.status === "rejected").length,
    redFlags: prospects.filter(p => p.has_warnings).length
