  const getStatusBadge = (statusStr) => {
    switch (statusStr) {
      case "approved": return <span className="badge badge-sangat-baik">DISETUJUI</span>;
      case "rejected": return <span className="badge badge-ditolak">DITOLAK</span>;
      case "auto_rejected": return <span className="badge badge-ditolak">REKOMENDASI TOLAK</span>;
      case "under_review": return <span className="badge badge-cukup">PROSES ANALISIS</span>;
      case "pending_ocr": return <span className="badge badge-baik">MENUNGGU DOKUMEN</span>;
      default: return <span className="badge badge-cukup">{statusStr}</span>;
    }
