            <div style={{ fontWeight: "700" }}>{user?.full_name}</div>
            <div style={{ fontSize: "0.8rem", color: "var(--text-secondary)", textTransform: "capitalize" }}>Role: {user?.role}</div>
          </div>
          <button onClick={logout} className="btn btn-secondary" style={{ padding: "8px 12px" }}>Keluar</button>
        </div>
      </div>

      {!selectedProspect ? (
        // =========================================================================
        // PROSPECT LIST VIEW
        // =========================================================================
        <>
          {/* Stats KPI Panel */}
          <div className="grid-4" style={{ marginBottom: "30px" }}>
            <div className="glass-panel" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <p style={{ fontSize: "0.8rem", fontWeight: "600", textTransform: "uppercase" }}>Total Pengajuan</p>
                <h2 style={{ fontSize: "2rem", color: "var(--accent-blue)", marginTop: "5px" }}>{stats.total}</h2>
              </div>
              <div style={{ fontSize: "2rem" }}>📋</div>
            </div>
            <div className="glass-panel" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <p style={{ fontSize: "0.8rem", fontWeight: "600", textTransform: "uppercase" }}>Disetujui Komite</p>
                <h2 style={{ fontSize: "2rem", color: "var(--success)", marginTop: "5px" }}>{stats.approved}</h2>
              </div>
              <div style={{ fontSize: "2rem" }}>✅</div>
            </div>
            <div className="glass-panel" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <p style={{ fontSize: "0.8rem", fontWeight: "600", textTransform: "uppercase" }}>Ditolak / Gagal</p>
                <h2 style={{ fontSize: "2rem", color: "var(--danger)", marginTop: "5px" }}>{stats.rejected}</h2>
              </div>
              <div style={{ fontSize: "2rem" }}>❌</div>
            </div>
            <div className="glass-panel" style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div>
                <p style={{ fontSize: "0.8rem", fontWeight: "600", textTransform: "uppercase" }}>Pemberitahuan Red Flag</p>
                <h2 style={{ fontSize: "2rem", color: "var(--warning)", marginTop: "5px" }}>{stats.redFlags}</h2>
              </div>
              <div style={{ fontSize: "2rem" }}>🚩</div>
            </div>
          </div>

          {/* Table Container */}
          <div className="glass-panel">
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px" }}>
              <h2>Daftar Prospek Penjaminan</h2>
              {(user?.role === "marketing" || user?.role === "admin") && (
                <button onClick={() => setActiveView("tambah")} className="btn btn-primary">
                  ➕ Buat Pengajuan Baru
                </button>
              )}
            </div>

            {loading ? (
              <p style={{ textAlign: "center", padding: "40px" }}>Memuat daftar pengajuan...</p>
