              <p style={{ textAlign: "center", padding: "40px", color: "var(--text-muted)" }}>
                Belum ada pengajuan terdaftar.
              </p>
            ) : (
              <div style={{ overflowX: "auto" }}>
                <table>
                  <thead>
                    <tr>
                      <th>Perusahaan & Proyek</th>
                      <th>Nilai Kontrak</th>
                      <th>Kategori Proyek</th>
                      <th>Skor Total</th>
                      <th>Kelayakan</th>
                      <th>Status Alur</th>
                      <th>Red Flag</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {prospects.map((p) => (
                      <tr key={p.id}>
                        <td>
                          <div style={{ fontWeight: "700" }}>{p.company_name}</div>
                          <div style={{ fontSize: "0.8rem", color: "var(--text-secondary)" }}>{p.project_name}</div>
                        </td>
                        <td>{formatCurrency(p.contract_value)}</td>
                        <td>{p.project_type}</td>
                        <td style={{ fontWeight: "700", color: "var(--accent-blue)" }}>
