                      </div>
                      <div>
                        <label>Proyek Sukses</label>
                        <div>{detailData.prospect.successful_projects} Proyek</div>
                      </div>
                      <div>
                        <label>Kolektabilitas OJK</label>
                        <div>Golongan {detailData.prospect.slik_collectibility}</div>
                      </div>
                      <div>
                        <label>Daftar Hitam</label>
                        <div>{detailData.prospect.blacklisted ? "Ya (Terdaftar)" : "Tidak"}</div>
                      </div>
                    </div>
