                          <span>Keuangan (35%)</span>
                          <span style={{ fontWeight: "700" }}>{detailData.prospect.score_keuangan.toFixed(1)} / 100</span>
                        </div>
                        <div style={{ height: "8px", background: "rgba(255,255,255,0.05)", borderRadius: "4px" }}>
