                      <div>
                        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                          <span>Pengalaman (20%)</span>
                          <span style={{ fontWeight: "700" }}>{detailData.prospect.score_pengalaman.toFixed(1)} / 100</span>
                        </div>
                        <div style={{ height: "8px", background: "rgba(255,255,255,0.05)", borderRadius: "4px" }}>
                          <div style={{ height: "100%", width: `${detailData.prospect.score_pengalaman}%`, background: "var(--accent-purple)", borderRadius: "4px" }}></div>
                        </div>
                      </div>

                      <div>
                        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                          <span>Legalitas (15%)</span>
                          <span style={{ fontWeight: "700" }}>{detailData.prospect.score_legalitas.toFixed(1)} / 100</span>
                        </div>
                        <div style={{ height: "8px", background: "rgba(255,255,255,0.05)", borderRadius: "4px" }}>
                          <div style={{ height: "100%", width: `${detailData.prospect.score_legalitas}%`, background: "var(--success)", borderRadius: "4px" }}></div>
                        </div>
                      </div>

                      <div>
                        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                          <span>Karakter (15%)</span>
                          <span style={{ fontWeight: "700" }}>{detailData.prospect.score_karakter.toFixed(1)} / 100</span>
                        </div>
                        <div style={{ height: "8px", background: "rgba(255,255,255,0.05)", borderRadius: "4px" }}>
                          <div style={{ height: "100%", width: `${detailData.prospect.score_karakter}%`, background: "var(--warning)", borderRadius: "4px" }}></div>
                        </div>
                      </div>

                      <div>
                        <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                          <span>Proyek (15%)</span>
                          <span style={{ fontWeight: "700" }}>{detailData.prospect.score_proyek.toFixed(1)} / 100</span>
                        </div>
                        <div style={{ height: "8px", background: "rgba(255,255,255,0.05)", borderRadius: "4px" }}>
                          <div style={{ height: "100%", width: `${detailData.prospect.score_proyek}%`, background: "var(--accent-blue-hover)", borderRadius: "4px" }}></div>
                        </div>
                      </div>
                    </div>

                    <div style={{ 
                      padding: "16px", 
                      borderRadius: "8px", 
                      background: "rgba(255,255,255,0.02)", 
