                          <label>Catatan Pertimbangan Komite</label>
                          <textarea 
                            className="input-control"
                            style={{ minHeight: "100px", resize: "vertical" }}
                            placeholder="Tuliskan alasan persetujuan atau penolakan pengajuan di sini..."
