                                  <tbody>
                                    {[
                                      { label: "Revenue", key: "revenue" },
                                      { label: "Net Profit", key: "net_profit" },
                                      { label: "Total Assets", key: "total_assets" },
                                      { label: "Liabilities", key: "total_liabilities" },
                                      { label: "Equity", key: "equity" },
                                      { label: "Aset Lancar", key: "current_assets" },
                                      { label: "Liabilitas Lancar", key: "current_liabilities" },
                                      { label: "Arus Kas Operasional", key: "operating_cash_flow" },
                                      { label: "Piutang Usaha", key: "accounts_receivable" },
                                    ].map((item) => (
                                      <tr key={item.key}>
                                        <td style={{ fontSize: "0.8rem", padding: "6px" }}>{item.label}</td>
                                        {ocrRows.map((row, idx) => (
                                          <td key={row.year} style={{ padding: "4px" }}>
                                            <input 
                                              type="number"
                                              className="input-control"
                                              style={{ 
                                                padding: "6px 8px", 
                                                fontSize: "0.8rem", 
                                                textAlign: "right",
                                                backgroundColor: "#0b0f19"
                                              }}
                                              value={row[item.key]}
                                              disabled={user?.role !== "analis" && user?.role !== "admin"}
                                              onChange={(e) => handleOcrCellChange(idx, item.key, e.target.value)}
                                            />
                                          </td>
                                        ))}
                                      </tr>
                                    ))}
                                  </tbody>
                                </table>
                              </div>

                              {(user?.role === "analis" || user?.role === "admin") && (
                                <button 
                                  onClick={handleSaveOcr} 
                                  className="btn btn-primary" 
                                  style={{ width: "100%", padding: "10px", fontSize: "0.85rem", marginTop: "15px" }}
                                  disabled={actionLoading}
                                >
                                  💾 Simpan & Verifikasi Koreksi Data
                                </button>
                              )}
                            </div>

                          </div>
                        </div>
                      )}
                    </div>
                  )}

                </div>

              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default CommonDashboard;

import React, { useState, useContext } from "react";
import { AuthContext } from "../context/AuthContext";

const MarketingDashboard = ({ setActiveView }) => {
  const { token, logout, user } = useContext(AuthContext);
  const [companyName, setCompanyName] = useState("");
  const [projectName, setProjectName] = useState("");
  const [contractValue, setContractValue] = useState("");
  const [projectType, setProjectType] = useState("Konstruksi");
  const [yearsOperating, setYearsOperating] = useState("3");
  const [successfulProjects, setSuccessfulProjects] = useState("5");
  const [slikCollectibility, setSlikCollectibility] = useState("1");
  const [blacklisted, setBlacklisted] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const formData = new FormData();
    formData.append("company_name", companyName);
    formData.append("project_name", projectName);
    formData.append("contract_value", parseFloat(contractValue) || 0.0);
    formData.append("project_type", projectType);
    formData.append("years_operating", parseInt(yearsOperating) || 0);
    formData.append("successful_projects", parseInt(successfulProjects) || 0);
    formData.append("slik_collectibility", parseInt(slikCollectibility) || 1);
    formData.append("blacklisted", blacklisted);

    try {
      const response = await fetch("http://127.0.0.1:8000/api/prospects", {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData
      });

      if (response.ok) {
        alert("Prospek penjaminan berhasil didaftarkan. Silakan unggah dokumen wajib.");
        setActiveView("daftar");
      } else {
        const err = await response.json();
        alert("Error: " + err.detail);
      }
    } catch (e) {
      alert("Gagal menambahkan prospek.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fade-in">
      <div className="topbar">
        <div>
          <h1>Form Pengajuan Penjaminan Baru</h1>
          <p>Input Profil Prospek & Data SLIK Awal (Peran: Marketing)</p>
        </div>
        <div style={{ display: "flex", gap: "15px", alignItems: "center" }}>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontWeight: "700" }}>{user?.full_name}</div>
            <div style={{ fontSize: "0.8rem", color: "var(--text-secondary)" }}>Role: {user?.role}</div>
          </div>
          <button onClick={logout} className="btn btn-secondary" style={{ padding: "8px 12px" }}>Keluar</button>
        </div>
      </div>

      <div style={{ marginBottom: "20px" }}>
        <button onClick={() => setActiveView("daftar")} className="btn btn-secondary">
          ⬅️ Kembali ke Daftar Prospek
        </button>
      </div>

      <div className="glass-panel" style={{ maxWidth: "800px", margin: "0 auto" }}>
        <h2 style={{ borderBottom: "1px solid var(--border-color)", paddingBottom: "10px", marginBottom: "20px" }}>
          Profil Prospek & Data Awal
        </h2>

        <form onSubmit={handleSubmit} style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px" }}>

          <div className="form-group" style={{ gridColumn: "span 2" }}>
            <label>Nama Perusahaan Nasabah</label>
            <input 
              type="text" 
              className="input-control" 
              placeholder="Contoh: PT Bangun Konstruksi Jaya"
              value={companyName}
              onChange={(e) => setCompanyName(e.target.value)}
              required
            />
          </div>

          <div className="form-group" style={{ gridColumn: "span 2" }}>
            <label>Nama Proyek Penjaminan</label>
            <input 
              type="text" 
              className="input-control" 
              placeholder="Contoh: Pembangunan Jembatan Tol Cikampek Tahap II"
              value={projectName}
              onChange={(e) => setProjectName(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label>Nilai Kontrak SPK (Rupiah)</label>
            <input 
              type="number" 
              className="input-control" 
              placeholder="Contoh: 12000000000"
              value={contractValue}
              onChange={(e) => setContractValue(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label>Jenis Proyek</label>
            <select 
              className="input-control"
              value={projectType}
              onChange={(e) => setProjectType(e.target.value)}
            >
              <option value="Konstruksi">Konstruksi (Tinggi Risiko)</option>
              <option value="Pengadaan">Pengadaan (Sedang Risiko)</option>
              <option value="Jasa Konsultasi">Jasa Konsultasi (Rendah Risiko)</option>
              <option value="Jasa Lainnya">Jasa Lainnya</option>
            </select>
          </div>

          <div className="form-group">
            <label>Pengalaman Operasional Perusahaan (Tahun)</label>
            <input 
              type="number" 
              className="input-control" 
              value={yearsOperating}
              onChange={(e) => setYearsOperating(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label>Jumlah Proyek Sukses Sebelumnya</label>
            <input 
              type="number" 
              className="input-control" 
              value={successfulProjects}
              onChange={(e) => setSuccessfulProjects(e.target.value)}
              required
            />
          </div>

          <div className="form-group">
            <label>Kolektabilitas OJK SLIK Pengurus</label>
            <select 
              className="input-control"
              value={slikCollectibility}
              onChange={(e) => setSlikCollectibility(e.target.value)}
            >
              <option value="1">Golongan 1: Lancar</option>
              <option value="2">Golongan 2: Dalam Perhatian Khusus</option>
              <option value="3">Golongan 3: Kurang Lancar (Red Flag)</option>
              <option value="4">Golongan 4: Diragukan (Red Flag)</option>
              <option value="5">Golongan 5: Macet (Red Flag)</option>
            </select>
          </div>

          <div className="form-group" style={{ display: "flex", flexDirection: "row", alignItems: "center", gap: "10px", marginTop: "24px" }}>
            <input 
              type="checkbox" 
              id="blacklisted"
              style={{ width: "20px", height: "20px", cursor: "pointer" }}
              checked={blacklisted}
              onChange={(e) => setBlacklisted(e.target.checked)}
            />
            <label htmlFor="blacklisted" style={{ cursor: "pointer", textTransform: "none", fontSize: "0.95rem" }}>
              Pengurus/Perusahaan Terdaftar Daftar Hitam
            </label>
          </div>

          <div style={{ gridColumn: "span 2", borderTop: "1px solid var(--border-color)", paddingTop: "20px", display: "flex", justifyContent: "flex-end" }}>
            <button 
              type="submit" 
              className="btn btn-primary" 
              style={{ padding: "12px 30px" }}
              disabled={loading}
            >
              {loading ? "Memproses..." : "Daftarkan & Lanjut ke Unggah Dokumen ➔"}
            </button>
          </div>

        </form>
      </div>
    </div>
  );
};

export default MarketingDashboard;

import React, { useState, useEffect, useContext } from "react";
import { AuthContext } from "../context/AuthContext";

const AdminDashboard = () => {
  const { token, logout, user } = useContext(AuthContext);
  const [configs, setConfigs] = useState({});
  const [auditLogs, setAuditLogs] = useState([]);
  const [loadingConfig, setLoadingConfig] = useState(false);
  const [loadingLogs, setLoadingLogs] = useState(false);
  const [saving, setSaving] = useState(false);

  // Fetch scoring configurations
  const fetchConfigs = async () => {
    setLoadingConfig(true);
    try {
      const response = await fetch("http://127.0.0.1:8000/api/admin/config", {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (response.ok) {
        const data = await response.json();
        setConfigs(data);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingConfig(false);
    }
  };

  // Fetch Audit Logs
  const fetchAuditLogs = async () => {
    setLoadingLogs(true);
    try {
      const response = await fetch("http://127.0.0.1:8000/api/admin/audit-logs", {
        headers: { Authorization: `Bearer ${token}` }
      });
      if (response.ok) {
        const data = await response.json();
        setAuditLogs(data);
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingLogs(false);
    }
  };

  useEffect(() => {
    fetchConfigs();
    fetchAuditLogs();
  }, []);

  const handleConfigChange = (key, val) => {
    setConfigs({
      ...configs,
      [key]: parseFloat(val) || 0.0
    });
  };

  const handleSaveConfig = async (e) => {
    e.preventDefault();

    // Validate that weights sum up to 100%
    const totalWeight = 
      (configs.weight_keuangan || 0) + 
      (configs.weight_pengalaman || 0) + 
      (configs.weight_legalitas || 0) + 
      (configs.weight_karakter || 0) + 
      (configs.weight_proyek || 0);

    if (Math.abs(totalWeight - 100.0) > 0.01) {
      alert(`Jumlah bobot 5 dimensi harus tepat 100%. Total bobot saat ini: ${totalWeight}%`);
      return;
    }

    setSaving(true);
    try {
      const response = await fetch("http://127.0.0.1:8000/api/admin/config", {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify(configs)
      });
      if (response.ok) {
        alert("Konfigurasi parameter skoring berhasil diperbarui & semua prospek telah dihitung ulang.");
        fetchConfigs();
        fetchAuditLogs(); // Refresh logs
      } else {
        alert("Gagal memperbarui konfigurasi.");
      }
    } catch (e) {
      alert("Terjadi kesalahan.");
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="fade-in">
      <div className="topbar">
        <div>
          <h1>Panel Administrator & Audit Trail</h1>
          <p>Konfigurasi Parameter Dinamis & Log Aktivitas Pengguna</p>
        </div>
        <div style={{ display: "flex", gap: "15px", alignItems: "center" }}>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontWeight: "700" }}>{user?.full_name}</div>
            <div style={{ fontSize: "0.8rem", color: "var(--text-secondary)" }}>Role: {user?.role}</div>
          </div>
          <button onClick={logout} className="btn btn-secondary" style={{ padding: "8px 12px" }}>Keluar</button>
        </div>
      </div>

      <div className="grid-2">
        {/* Left Side: Score Weights Configuration */}
        <div className="glass-panel">
          <h2 style={{ borderBottom: "1px solid var(--border-color)", paddingBottom: "10px", marginBottom: "20px" }}>
            Konfigurasi Parameter Skoring Dinamis
          </h2>

          {loadingConfig ? (
            <p>Memuat konfigurasi...</p>
          ) : (
            <form onSubmit={handleSaveConfig} style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
              <h3 style={{ fontSize: "1rem", color: "var(--accent-blue)", marginTop: "10px" }}>Bobot Persentase 5 Dimensi (Total Harus 100%)</h3>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "15px" }}>
                <div className="form-group">
                  <label>Dimensi Keuangan (%)</label>
                  <input 
                    type="number" 
                    step="0.1"
                    className="input-control"
                    value={configs.weight_keuangan || ""}
                    onChange={(e) => handleConfigChange("weight_keuangan", e.target.value)}
                  />
                </div>
                <div className="form-group">
                  <label>Dimensi Pengalaman (%)</label>
                  <input 
                    type="number" 
                    step="0.1"
                    className="input-control"
                    value={configs.weight_pengalaman || ""}
                    onChange={(e) => handleConfigChange("weight_pengalaman", e.target.value)}
                  />
                </div>
                <div className="form-group">
                  <label>Dimensi Legalitas (%)</label>
                  <input 
                    type="number" 
                    step="0.1"
                    className="input-control"
                    value={configs.weight_legalitas || ""}
                    onChange={(e) => handleConfigChange("weight_legalitas", e.target.value)}
                  />
                </div>
                <div className="form-group">
                  <label>Dimensi Karakter (%)</label>
                  <input 
                    type="number" 
                    step="0.1"
                    className="input-control"
                    value={configs.weight_karakter || ""}
                    onChange={(e) => handleConfigChange("weight_karakter", e.target.value)}
                  />
                </div>
                <div className="form-group" style={{ gridColumn: "span 2" }}>
                  <label>Dimensi Proyek (%)</label>
                  <input 
                    type="number" 
                    step="0.1"
                    className="input-control"
                    value={configs.weight_proyek || ""}
                    onChange={(e) => handleConfigChange("weight_proyek", e.target.value)}
                  />
                </div>
              </div>

              <h3 style={{ fontSize: "1rem", color: "var(--accent-blue)", marginTop: "15px" }}>Nilai Batas Rasio Keuangan & Red Flag</h3>

              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "15px" }}>
                <div className="form-group">
                  <label>DER Sehat (Kurang Dari)</label>
                  <input 
                    type="number" 
                    step="0.1"
                    className="input-control"
                    value={configs.der_threshold_healthy || ""}
                    onChange={(e) => handleConfigChange("der_threshold_healthy", e.target.value)}
                  />
                </div>
                <div className="form-group">
                  <label>DER Maksimal (Red Flag)</label>
                  <input 
                    type="number" 
                    step="0.1"
                    className="input-control"
                    value={configs.der_threshold_max || ""}
                    onChange={(e) => handleConfigChange("der_threshold_max", e.target.value)}
                  />
                </div>
                <div className="form-group">
                  <label>Current Ratio Sehat (Lebih Dari)</label>
                  <input 
                    type="number" 
                    step="0.1"
                    className="input-control"
                    value={configs.current_ratio_healthy || ""}
                    onChange={(e) => handleConfigChange("current_ratio_healthy", e.target.value)}
                  />
                </div>
                <div className="form-group">
                  <label>Periode AR Sehat (Hari)</label>
                  <input 
                    type="number" 
                    step="1"
                    className="input-control"
                    value={configs.collection_days_healthy || ""}
                    onChange={(e) => handleConfigChange("collection_days_healthy", e.target.value)}
                  />
                </div>
                <div className="form-group" style={{ gridColumn: "span 2" }}>
                  <label>Periode AR Maksimal (Hari)</label>
                  <input 
                    type="number" 
                    step="1"
                    className="input-control"
                    value={configs.collection_days_max || ""}
                    onChange={(e) => handleConfigChange("collection_days_max", e.target.value)}
                  />
                </div>
              </div>

              <button type="submit" className="btn btn-primary" style={{ marginTop: "15px" }} disabled={saving}>
                {saving ? "Menyimpan & Menghitung Ulang..." : "Simpan Parameter Konfigurasi"}
              </button>
            </form>
          )}
        </div>

        {/* Right Side: Audit Trail Logs */}
        <div className="glass-panel" style={{ display: "flex", flexDirection: "column" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: "1px solid var(--border-color)", paddingBottom: "10px", marginBottom: "20px" }}>
            <h2>Audit Trail Aktivitas</h2>
            <button onClick={fetchAuditLogs} className="btn btn-secondary" style={{ padding: "6px 12px", fontSize: "0.8rem" }}>
              🔄 Refresh Log
            </button>
          </div>

          {loadingLogs ? (
            <p>Memuat audit logs...</p>
          ) : auditLogs.length === 0 ? (
            <p style={{ color: "var(--text-muted)", textAlign: "center", padding: "40px" }}>Belum ada log aktivitas.</p>
          ) : (
            <div style={{ flex: 1, maxHeight: "550px", overflowY: "auto" }}>
              <table style={{ fontSize: "0.85rem" }}>
                <thead>
                  <tr>
                    <th>Waktu</th>
                    <th>User</th>
                    <th>Aktivitas</th>
                  </tr>
                </thead>
                <tbody>
                  {auditLogs.map((log) => (
                    <tr key={log.id}>
                      <td style={{ color: "var(--text-muted)", whiteSpace: "nowrap" }}>
                        {new Date(log.timestamp).toLocaleString("id-ID")}
                      </td>
                      <td style={{ fontWeight: "700" }}>{log.username}</td>
                      <td>
                        <span className="badge badge-baik" style={{ fontSize: "0.65rem", padding: "2px 6px", marginRight: "6px" }}>
                          {log.action}
                        </span>
                        {log.details}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

      </div>
    </div>
  );
};

export default AdminDashboard;

import React, { useContext, useState } from "react";
import { AuthProvider, AuthContext } from "./context/AuthContext";
import Login from "./views/Login";
import CommonDashboard from "./views/CommonDashboard";
import MarketingDashboard from "./views/MarketingDashboard";
import AdminDashboard from "./views/AdminDashboard";

function AppContent() {
  const { user, loading } = useContext(AuthContext);
  const [activeView, setActiveView] = useState("daftar"); // 'daftar', 'tambah', 'admin'

  if (loading) {
    return (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: "100vh", backgroundColor: "var(--bg-primary)" }}>
        <p>Memuat Sistem Skoring AI Underwriting...</p>
      </div>
    );
  }

  if (!user) {
    return <Login />;
  }

  const renderActiveView = () => {
    switch (activeView) {
      case "daftar":
        return <CommonDashboard setActiveView={setActiveView} />;
      case "tambah":
        return <MarketingDashboard setActiveView={setActiveView} />;
      case "admin":
        return <AdminDashboard />;
      default:
        return <CommonDashboard setActiveView={setActiveView} />;
    }
  };

  return (
    <div className="layout-container">
      {/* Sidebar Navigation */}
      <div className="sidebar">
        <div className="sidebar-brand">
          <span style={{ fontSize: "1.5rem" }}>🤖</span>
          <h3>UNDERWRITE AI</h3>
        </div>

        <ul className="sidebar-menu">
          <li>
            <div 
              onClick={() => setActiveView("daftar")} 
              className={`sidebar-link ${activeView === "daftar" ? "active" : ""}`}
            >
              <span>📊</span> Dasbor Skoring
            </div>
          </li>
          {(user.role === "marketing" || user.role === "admin") && (
            <li>
              <div 
                onClick={() => setActiveView("tambah")} 
                className={`sidebar-link ${activeView === "tambah" ? "active" : ""}`}
              >
                <span>📝</span> Buat Pengajuan
              </div>
            </li>
          )}
          {user.role === "admin" && (
            <li>
              <div 
                onClick={() => setActiveView("admin")} 
                className={`sidebar-link ${activeView === "admin" ? "active" : ""}`}
              >
                <span>🛠️</span> Parameter & Audit
              </div>
            </li>
          )}
        </ul>

        <div style={{ marginTop: "auto", borderTop: "1px solid var(--border-color)", paddingTop: "15px" }}>
          <div style={{ fontSize: "0.8rem", color: "var(--text-muted)" }}>Sistem Skoring v1.0</div>
          <div style={{ fontSize: "0.75rem", color: "var(--text-muted)", marginTop: "2px" }}>On-Premise Offline Mode</div>
        </div>
      </div>

      {/* Main Panel Content */}
      <div className="main-content">
        {renderActiveView()}
      </div>
    </div>
  );
}

function App() {
  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
}

export default App;

