import React, { useState, useEffect, useContext } from "react";
import { AuthContext } from "../context/AuthContext";

// ─────────────────────────────────────────────────
// Analyst Decision Panel – shown inside detail view
// ─────────────────────────────────────────────────
const AnalystDecisionPanel = ({ prospectId, detailData, token, onDecisionMade }) => {
  const [action, setAction] = useState("forward_to_komite");
  const [notes, setNotes] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!notes.trim()) {
      alert("Catatan/komentar analis wajib diisi sebelum mengambil keputusan.");
      return;
    }

    const confirmMessages = {
      reject_to_marketing: `Kembalikan pengajuan "${detailData.prospect.company_name}" ke Marketing?\n\nMarketing akan melihat catatan Anda dan diminta melengkapi dokumen.`,
      accept_by_analis: `Setujui pengajuan "${detailData.prospect.company_name}" dalam wewenang Analis?\n\nStatus akan langsung menjadi DISETUJUI tanpa perlu Komite.`,
      forward_to_komite: `Teruskan pengajuan "${detailData.prospect.company_name}" ke Komite untuk keputusan final?`,
    };

    if (!window.confirm(confirmMessages[action])) return;

    setLoading(true);
    const formData = new FormData();
    formData.append("action", action);
    formData.append("notes", notes);

    try {
      const res = await fetch(`http://127.0.0.1:8000/api/prospects/${prospectId}/analis-review`, {
        method: "POST",
        headers: { Authorization: `Bearer ${token}` },
        body: formData,
      });

      if (res.ok) {
        const data = await res.json();
        alert(`✅ ${data.message}`);
        onDecisionMade();
      } else {
        const err = await res.json();
        alert("❌ Error: " + err.detail);
      }
    } catch (e) {
      alert("Gagal menghubungi server.");
    } finally {
      setLoading(false);
    }
  };

  const actionOptions = [
    {
      value: "reject_to_marketing",
      label: "🔴 Kembalikan ke Marketing",
      desc: "Dokumen kurang / perlu diperbaiki. Marketing harus melengkapi sebelum bisa diproses ulang.",
      color: "var(--danger)",
      bg: "rgba(239,68,68,0.07)",
      border: "rgba(239,68,68,0.3)",
    },
    {
      value: "accept_by_analis",
      label: "🟢 Setujui (Dalam Wewenang Analis)",
      desc: "Pengajuan memenuhi syarat dan berada di bawah limit wewenang analis. Tidak perlu ke Komite.",
      color: "var(--success)",
      bg: "rgba(34,197,94,0.07)",
      border: "rgba(34,197,94,0.3)",
    },
    {
      value: "forward_to_komite",
      label: "🔵 Teruskan ke Komite",
      desc: "Nilai kontrak atau risiko melebihi limit wewenang analis. Komite harus memberi keputusan final.",
      color: "var(--accent-blue)",
      bg: "rgba(59,130,246,0.07)",
      border: "rgba(59,130,246,0.3)",
    },
  ];

  const selected = actionOptions.find((o) => o.value === action);

  return (
    <div className="glass-panel" style={{ border: "1px solid rgba(139,92,246,0.3)" }}>
      <h3
        style={{
          borderBottom: "1px solid var(--border-color)",
          paddingBottom: "10px",
          marginBottom: "20px",
          display: "flex",
          alignItems: "center",
          gap: "8px",
          color: "var(--accent-purple)",
        }}
      >
        🔍 Keputusan Analis
      </h3>

      {/* Existing decision notice */}
      {detailData.prospect.analis_action && (
        <div
          className="alert alert-warning"
          style={{ marginBottom: "20px", fontSize: "0.9rem" }}
        >
          <strong>⚠️ Keputusan sebelumnya sudah ada:</strong>{" "}
          <span style={{ textTransform: "uppercase" }}>
            {detailData.prospect.analis_action.replace(/_/g, " ")}
          </span>
          <br />
          <span style={{ color: "var(--text-secondary)" }}>
            {detailData.prospect.analis_notes}
          </span>
          <br />
          <small style={{ color: "var(--text-muted)" }}>
            Anda dapat mengubah keputusan dengan mengisi form di bawah.
          </small>
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
        {/* Action selector cards */}
        <div>
          <label style={{ marginBottom: "10px", display: "block" }}>Pilih Tindakan</label>
          <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
            {actionOptions.map((opt) => (
              <label
                key={opt.value}
                htmlFor={`action-${opt.value}`}
                style={{
                  display: "flex",
                  alignItems: "flex-start",
                  gap: "12px",
                  padding: "14px 16px",
                  borderRadius: "10px",
                  border: `1px solid ${action === opt.value ? opt.border : "var(--border-color)"}`,
                  background: action === opt.value ? opt.bg : "transparent",
                  cursor: "pointer",
                  transition: "all 0.2s ease",
                }}
              >
                <input
                  type="radio"
                  id={`action-${opt.value}`}
                  name="analis_action"
                  value={opt.value}
                  checked={action === opt.value}
                  onChange={() => setAction(opt.value)}
                  style={{ marginTop: "3px", accentColor: opt.color, flexShrink: 0 }}
                />
                <div>
                  <div style={{ fontWeight: "700", color: action === opt.value ? opt.color : "var(--text-primary)" }}>
                    {opt.label}
                  </div>
                  <div style={{ fontSize: "0.8rem", color: "var(--text-secondary)", marginTop: "3px" }}>
                    {opt.desc}
                  </div>
                </div>
              </label>
            ))}
          </div>
        </div>

        {/* Notes textarea */}
        <div className="form-group" style={{ margin: 0 }}>
          <label>
            Catatan / Komentar Analis <span style={{ color: "var(--danger)" }}>*</span>
          </label>
          {action === "reject_to_marketing" && (
            <div
              style={{
                fontSize: "0.8rem",
                color: "var(--warning)",
                marginBottom: "8px",
                padding: "8px 12px",
                background: "rgba(245,158,11,0.08)",
                borderRadius: "6px",
                border: "1px solid rgba(245,158,11,0.2)",
              }}
            >
              💡 Cantumkan dokumen apa yang kurang atau perlu diperbaiki agar Marketing mengetahui tindakan selanjutnya.
            </div>
          )}
          <textarea
            className="input-control"
            style={{ minHeight: "120px", resize: "vertical" }}
            placeholder={
              action === "reject_to_marketing"
                ? "Contoh: Laporan keuangan tahun 2023 tidak lengkap. Mohon sertakan neraca konsolidasi dan laporan arus kas yang telah diaudit."
                : action === "accept_by_analis"
                ? "Contoh: Semua dokumen lengkap, rasio keuangan sehat, SLIK Golongan 1. Disetujui sesuai limit wewenang analis."
                : "Contoh: Nilai kontrak di atas Rp 5 Miliar memerlukan persetujuan Komite. Analisis telah selesai dan rekomendasikan untuk disetujui."
            }
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            required
          />
        </div>

        {/* Submit button */}
        <button
          type="submit"
          disabled={loading || !notes.trim()}
          style={{
            padding: "14px",
            borderRadius: "10px",
            border: "none",
            fontWeight: "700",
            fontSize: "1rem",
            cursor: loading || !notes.trim() ? "not-allowed" : "pointer",
            background: selected?.color || "var(--accent-blue)",
            color: "#fff",
            opacity: loading || !notes.trim() ? 0.5 : 1,
            transition: "all 0.2s ease",
          }}
        >
          {loading ? "⏳ Memproses..." : `✔ Kirim Keputusan: ${selected?.label}`}
        </button>
      </form>
    </div>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// MAIN ANALIS DASHBOARD
// ─────────────────────────────────────────────────────────────────────────────
const AnalisDashboard = () => {
  const { user, token, logout } = useContext(AuthContext);
  const [prospects, setProspects] = useState([]);
  const [selectedProspect, setSelectedProspect] = useState(null);
  const [detailData, setDetailData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [ocrRows, setOcrRows] = useState([]);
  const [filterStatus, setFilterStatus] = useState("all");

  const fetchProspects = async () => {
    setLoading(true);
    try {
      const res = await fetch("http://127.0.0.1:8000/api/prospects", {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) setProspects(await res.json());
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const fetchDetail = async (id) => {
    try {
      const res = await fetch(`http://127.0.0.1:8000/api/prospects/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setDetailData(data);
        if (data.financial_data) {
          setOcrRows(JSON.parse(JSON.stringify(data.financial_data)));
        }
      }
    } catch (e) {
      console.error(e);
    }
  };

  useEffect(() => {
    fetchProspects();
  }, []);

  const handleSelectProspect = (id) => {
    setSelectedProspect(id);
    fetchDetail(id);
  };

  const handleBackToList = () => {
    setSelectedProspect(null);
    setDetailData(null);
    fetchProspects();
  };

  const handleDecisionMade = () => {
    fetchDetail(selectedProspect);
    fetchProspects();
  };

  // OCR editing
  const handleOcrCellChange = (index, field, value) => {
    const updated = [...ocrRows];
    updated[index][field] = parseFloat(value) || 0.0;
    setOcrRows(updated);
  };

  const handleSaveOcr = async () => {
    setActionLoading(true);
    try {
      const res = await fetch(
        `http://127.0.0.1:8000/api/prospects/${selectedProspect}/verify-ocr`,
        {
          method: "PUT",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify(ocrRows),
        }
      );
      if (res.ok) {
        alert("✅ Data keuangan berhasil diverifikasi & skoring diperbarui.");
        fetchDetail(selectedProspect);
      } else {
        alert("Gagal menyimpan data keuangan.");
      }
    } catch (e) {
      alert("Gagal mengirim data verifikasi.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleBypassBlur = async () => {
    if (!window.confirm("Bypass verifikasi kualitas dokumen secara manual?")) return;
    setActionLoading(true);
    try {
      const res = await fetch(
        `http://127.0.0.1:8000/api/prospects/${selectedProspect}/bypass-blur`,
        { method: "POST", headers: { Authorization: `Bearer ${token}` } }
      );
      if (res.ok) {
        alert("Pemeriksaan kualitas berhasil di-bypass.");
        fetchDetail(selectedProspect);
      }
    } catch {
      alert("Gagal melakukan bypass.");
    } finally {
      setActionLoading(false);
    }
  };

  // Filter helpers
  const statusGroups = {
    all: prospects,
    pending: prospects.filter((p) =>
      ["pending_ocr", "returned_to_marketing"].includes(p.status)
    ),
    needs_review: prospects.filter((p) => p.status === "under_review"),
    decided: prospects.filter((p) =>
      ["approved", "rejected"].includes(p.status)
    ),
  };

  const displayProspects = statusGroups[filterStatus] || prospects;

  const stats = {
    total: prospects.length,
    needs_review: prospects.filter((p) => p.status === "under_review").length,
    returned: prospects.filter((p) => p.status === "returned_to_marketing").length,
    approved: prospects.filter((p) => p.status === "approved").length,
  };

  // ── Formatters ──
  const formatCurrency = (v) =>
    new Intl.NumberFormat("id-ID", {
      style: "currency",
      currency: "IDR",
      maximumFractionDigits: 0,
    }).format(v);

  const getStatusBadge = (s) => {
    const map = {
      approved: { label: "DISETUJUI", cls: "badge-sangat-baik" },
      rejected: { label: "DITOLAK", cls: "badge-ditolak" },
      auto_rejected: { label: "REKOMENDASI TOLAK", cls: "badge-ditolak" },
      under_review: { label: "PROSES ANALISIS", cls: "badge-cukup" },
      pending_ocr: { label: "MENUNGGU DOKUMEN", cls: "badge-baik" },
      returned_to_marketing: { label: "DIKEMBALIKAN KE MARKETING", cls: "badge-kurang" },
    };
    const info = map[s] || { label: s, cls: "badge-cukup" };
    return <span className={`badge ${info.cls}`}>{info.label}</span>;
  };

  const getScoreBadge = (cat) => {
    if (!cat) return <span className="badge badge-cukup">-</span>;
    const clean = cat.toLowerCase().replace(" ", "-");
    return <span className={`badge badge-${clean}`}>{cat}</span>;
  };

  return (
    <div className="fade-in">
      {/* TOP BAR */}
      <div className="topbar">
        <div>
          <h1>Dasbor Analis Underwriting</h1>
          <p>Verifikasi Dokumen, Koreksi Data OCR & Keputusan Penerusan</p>
        </div>
        <div style={{ display: "flex", gap: "15px", alignItems: "center" }}>
          <div style={{ textAlign: "right" }}>
            <div style={{ fontWeight: "700" }}>{user?.full_name}</div>
            <div style={{ fontSize: "0.8rem", color: "var(--text-secondary)", textTransform: "capitalize" }}>
              Role: {user?.role}
            </div>
          </div>
          <button onClick={logout} className="btn btn-secondary" style={{ padding: "8px 12px" }}>
            Keluar
          </button>
        </div>
      </div>

      {!selectedProspect ? (
        <>
          {/* KPI Stats */}
          <div className="grid-4" style={{ marginBottom: "30px" }}>
            {[
              { label: "Total Pengajuan", val: stats.total, icon: "📋", color: "var(--accent-blue)" },
              { label: "Perlu Ditinjau", val: stats.needs_review, icon: "🔍", color: "var(--accent-purple)" },
              { label: "Dikembalikan ke Marketing", val: stats.returned, icon: "↩️", color: "var(--warning)" },
              { label: "Disetujui", val: stats.approved, icon: "✅", color: "var(--success)" },
            ].map((stat) => (
              <div
                key={stat.label}
                className="glass-panel"
                style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}
              >
                <div>
                  <p style={{ fontSize: "0.8rem", fontWeight: "600", textTransform: "uppercase" }}>
                    {stat.label}
                  </p>
                  <h2 style={{ fontSize: "2rem", color: stat.color, marginTop: "5px" }}>{stat.val}</h2>
                </div>
                <div style={{ fontSize: "2rem" }}>{stat.icon}</div>
              </div>
            ))}
          </div>

          {/* Filter Tabs */}
          <div className="glass-panel">
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: "20px", flexWrap: "wrap", gap: "12px" }}>
              <h2>Daftar Pengajuan untuk Ditinjau</h2>
              <div style={{ display: "flex", gap: "8px", flexWrap: "wrap" }}>
                {[
                  { key: "all", label: "Semua" },
                  { key: "needs_review", label: "🔍 Perlu Ditinjau" },
                  { key: "pending", label: "⏳ Menunggu Dokumen" },
                  { key: "decided", label: "✅ Sudah Diputuskan" },
                ].map((tab) => (
                  <button
                    key={tab.key}
                    onClick={() => setFilterStatus(tab.key)}
                    className={`btn ${filterStatus === tab.key ? "btn-primary" : "btn-secondary"}`}
                    style={{ padding: "6px 14px", fontSize: "0.85rem" }}
                  >
                    {tab.label}
                  </button>
                ))}
              </div>
            </div>

            {loading ? (
              <p style={{ textAlign: "center", padding: "40px" }}>Memuat daftar pengajuan...</p>
            ) : displayProspects.length === 0 ? (
              <p style={{ textAlign: "center", padding: "40px", color: "var(--text-muted)" }}>
                Tidak ada pengajuan dalam kategori ini.
              </p>
            ) : (
              <div style={{ overflowX: "auto" }}>
                <table>
                  <thead>
                    <tr>
                      <th>Perusahaan & Proyek</th>
                      <th>Nilai Kontrak</th>
                      <th>Skor Total</th>
                      <th>Kelayakan</th>
                      <th>Status Alur</th>
                      <th>Red Flag</th>
                      <th>Keputusan Analis</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {displayProspects.map((p) => (
                      <tr key={p.id}>
                        <td>
                          <div style={{ fontWeight: "700" }}>{p.company_name}</div>
                          <div style={{ fontSize: "0.8rem", color: "var(--text-secondary)" }}>
                            {p.project_name}
                          </div>
                        </td>
                        <td>{formatCurrency(p.contract_value)}</td>
                        <td style={{ fontWeight: "700", color: "var(--accent-blue)" }}>
                          {p.score_total > 0 ? p.score_total.toFixed(2) : "-"}
                        </td>
                        <td>{getScoreBadge(p.score_category)}</td>
                        <td>{getStatusBadge(p.status)}</td>
                        <td>
                          {p.has_warnings ? (
                            <span style={{ color: "var(--warning)", fontWeight: "bold" }}>
                              🚩 {p.warnings_count} Warning
                            </span>
                          ) : (
                            <span style={{ color: "var(--success)" }}>🟢 Aman</span>
                          )}
                        </td>
                        <td>
                          {p.analis_action ? (
                            <span
                              style={{
                                fontSize: "0.75rem",
                                padding: "3px 8px",
                                borderRadius: "4px",
                                background:
                                  p.analis_action === "reject_to_marketing"
                                    ? "rgba(239,68,68,0.15)"
                                    : p.analis_action === "accept_by_analis"
                                    ? "rgba(34,197,94,0.15)"
                                    : "rgba(59,130,246,0.15)",
                                color:
                                  p.analis_action === "reject_to_marketing"
                                    ? "var(--danger)"
                                    : p.analis_action === "accept_by_analis"
                                    ? "var(--success)"
                                    : "var(--accent-blue)",
                                fontWeight: "600",
                              }}
                            >
                              {p.analis_action === "reject_to_marketing"
                                ? "↩ Ke Marketing"
                                : p.analis_action === "accept_by_analis"
                                ? "✓ Disetujui"
                                : "→ Ke Komite"}
                            </span>
                          ) : (
                            <span style={{ color: "var(--text-muted)", fontSize: "0.8rem" }}>
                              Belum diputuskan
                            </span>
                          )}
                        </td>
                        <td>
                          <button
                            onClick={() => handleSelectProspect(p.id)}
                            className="btn btn-secondary"
                            style={{ padding: "6px 12px", fontSize: "0.85rem" }}
                          >
                            Tinjau Detail
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </>
      ) : (
        // ─────────────────────────────────────────────────
        // DETAIL VIEW
        // ─────────────────────────────────────────────────
        <>
          <div style={{ marginBottom: "20px" }}>
            <button onClick={handleBackToList} className="btn btn-secondary">
              ⬅️ Kembali ke Dasbor Analis
            </button>
          </div>

          {!detailData ? (
            <p>Memuat rincian data prospek...</p>
          ) : (
            <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
              {/* Red Flags */}
              {detailData.warnings && detailData.warnings.length > 0 && (
                <div
                  className="alert alert-danger"
                  style={{ display: "flex", flexDirection: "column", gap: "10px" }}
                >
                  <h4
                    style={{
                      color: "var(--danger)",
                      display: "flex",
                      alignItems: "center",
                      gap: "8px",
                      fontWeight: "800",
                    }}
                  >
                    ⚠️ RED FLAGS DETECTED (PERINGATAN SISTEM)
                  </h4>
                  <ul style={{ paddingLeft: "20px" }}>
                    {detailData.warnings.map((w, idx) => (
                      <li key={idx} style={{ marginBottom: "6px" }}>
                        <strong>
                          [{w.stage}] {w.type}:
                        </strong>{" "}
                        {w.message}
                        {w.auto_reject && (
                          <span
                            style={{
                              marginLeft: "8px",
                              fontSize: "0.75rem",
                              background: "rgba(239,68,68,0.2)",
                              color: "var(--danger)",
                              padding: "2px 6px",
                              borderRadius: "4px",
                            }}
                          >
                            SARAN TOLAK
                          </span>
                        )}
                      </li>
                    ))}
                  </ul>
                  {detailData.prospect.has_blur_document && !detailData.prospect.bypass_manual && (
                    <button
                      onClick={handleBypassBlur}
                      className="btn btn-danger"
                      style={{
                        padding: "6px 14px",
                        fontSize: "0.8rem",
                        marginTop: "5px",
                        alignSelf: "flex-start",
                      }}
                      disabled={actionLoading}
                    >
                      Bypass Kualitas Dokumen secara Manual
                    </button>
                  )}
                </div>
              )}

              {/* Catatan dari analis sebelumnya (jika sudah ada) */}
              {detailData.prospect.analis_notes && (
                <div
                  style={{
                    padding: "16px 20px",
                    borderRadius: "10px",
                    background: "rgba(139,92,246,0.08)",
                    border: "1px solid rgba(139,92,246,0.25)",
                  }}
                >
                  <div style={{ fontWeight: "700", marginBottom: "6px", color: "var(--accent-purple)" }}>
                    📝 Catatan Analis Sebelumnya
                  </div>
                  <div style={{ color: "var(--text-secondary)", fontSize: "0.9rem", lineHeight: "1.6" }}>
                    {detailData.prospect.analis_notes}
                  </div>
                  {detailData.analis_reviewer && (
                    <div style={{ marginTop: "8px", fontSize: "0.78rem", color: "var(--text-muted)" }}>
                      — {detailData.analis_reviewer.full_name}
                    </div>
                  )}
                </div>
              )}

              <div className="grid-2">
                {/* LEFT SIDE */}
                <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
                  {/* Prospect Info */}
                  <div className="glass-panel">
                    <h3
                      style={{
                        borderBottom: "1px solid var(--border-color)",
                        paddingBottom: "10px",
                        marginBottom: "15px",
                      }}
                    >
                      Informasi Ringkas
                    </h3>
                    <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "15px" }}>
                      {[
                        { label: "Nama Perusahaan", val: detailData.prospect.company_name },
                        { label: "Nama Proyek", val: detailData.prospect.project_name },
                        {
