                        { label: "Pengalaman", val: `${detailData.prospect.years_operating} Tahun` },
                        { label: "Proyek Sukses", val: `${detailData.prospect.successful_projects} Proyek` },
                        {
                          label: "Kolektabilitas OJK",
                          val: `Golongan ${detailData.prospect.slik_collectibility}`,
                        },
                        {
                          label: "Daftar Hitam",
                          val: detailData.prospect.blacklisted ? "Ya (Terdaftar)" : "Tidak",
                        },
                      ].map((item) => (
                        <div key={item.label}>
                          <label>{item.label}</label>
                          <div style={{ fontWeight: "700", color: item.color || "inherit" }}>
                            {item.val}
