                        paddingBottom: "10px",
                        marginBottom: "15px",
                      }}
                    >
                      Analisis Skoring 5 Dimensi
                    </h3>
                    <div style={{ display: "flex", flexDirection: "column", gap: "15px", marginBottom: "25px" }}>
                      {[
                        { label: "Keuangan (35%)", key: "score_keuangan", color: "var(--accent-blue)" },
                        { label: "Pengalaman (20%)", key: "score_pengalaman", color: "var(--accent-purple)" },
                        { label: "Legalitas (15%)", key: "score_legalitas", color: "var(--success)" },
                        { label: "Karakter (15%)", key: "score_karakter", color: "var(--warning)" },
                        { label: "Proyek (15%)", key: "score_proyek", color: "var(--accent-blue-hover)" },
                      ].map((dim) => (
                        <div key={dim.key}>
                          <div
                            style={{
                              display: "flex",
                              justifyContent: "space-between",
                              marginBottom: "5px",
                            }}
                          >
                            <span>{dim.label}</span>
                            <span style={{ fontWeight: "700" }}>
                              {detailData.prospect[dim.key].toFixed(1)} / 100
                            </span>
                          </div>
                          <div
                            style={{
                              height: "8px",
                              background: "rgba(255,255,255,0.05)",
                              borderRadius: "4px",
                            }}
                          >
                            <div
                              style={{
                                height: "100%",
                                width: `${detailData.prospect[dim.key]}%`,
                                background: dim.color,
                                borderRadius: "4px",
                                transition: "width 0.6s ease",
                              }}
                            />
                          </div>
                        </div>
                      ))}
                    </div>
                    <div
                      style={{
                        padding: "16px",
                        borderRadius: "8px",
                        background: "rgba(255,255,255,0.02)",
                        border: "1px solid var(--border-color)",
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                      }}
                    >
                      <div>
                        <div style={{ fontSize: "0.85rem", color: "var(--text-secondary)" }}>
                          SKOR KELAYAKAN AKHIR
                        </div>
                        <div
                          style={{
                            fontSize: "2rem",
                            fontWeight: "800",
                            color: "var(--accent-blue)",
                            marginTop: "2px",
                          }}
                        >
                          {detailData.prospect.score_total.toFixed(2)}
                        </div>
                      </div>
                      <div style={{ textAlign: "right" }}>
                        <div style={{ fontSize: "0.85rem", color: "var(--text-secondary)" }}>
                          KLASIFIKASI RISIKO
                        </div>
                        <div style={{ marginTop: "5px" }}>
                          {getScoreBadge(detailData.prospect.score_category)}
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Download Reports */}
                  <div className="glass-panel">
                    <h3
                      style={{
                        borderBottom: "1px solid var(--border-color)",
                        paddingBottom: "10px",
                        marginBottom: "15px",
                      }}
                    >
                      Berkas & Laporan
                    </h3>
                    <div style={{ display: "flex", flexWrap: "wrap", gap: "10px" }}>
                      <a
                        href={`http://127.0.0.1:8000/api/prospects/${selectedProspect}/pdf?token=${token}`}
                        target="_blank"
                        rel="noreferrer"
                        className="btn btn-primary"
                        style={{ flex: 1, minWidth: "150px" }}
                      >
                        📄 Unduh Credit Memo (PDF)
                      </a>
                      <a
                        href={`http://127.0.0.1:8000/api/prospects/${selectedProspect}/excel?token=${token}`}
                        className="btn btn-secondary"
                        style={{ flex: 1, minWidth: "150px" }}
                      >
                        📊 Ekspor Analisis (.xlsx)
                      </a>
                    </div>
                  </div>

                  {/* ── ANALYST DECISION PANEL ── */}
                  <AnalystDecisionPanel
                    prospectId={selectedProspect}
                    detailData={detailData}
                    token={token}
                    onDecisionMade={handleDecisionMade}
                  />
                </div>

                {/* RIGHT SIDE */}
                <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
                  {/* Document Checklist */}
                  <div className="glass-panel">
                    <h3
                      style={{
                        borderBottom: "1px solid var(--border-color)",
                        paddingBottom: "10px",
                        marginBottom: "15px",
                      }}
                    >
                      Dokumen Wajib & Persyaratan (10 Berkas)
                    </h3>
                    <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
                      {detailData.documents.map((doc) => (
                        <div
                          key={doc.id}
                          style={{
                            display: "flex",
                            justifyContent: "space-between",
                            alignItems: "center",
                            padding: "12px 16px",
                            border: "1px solid var(--border-color)",
                            borderRadius: "8px",
                          }}
                        >
                          <div>
                            <div style={{ fontWeight: "700", fontSize: "0.95rem" }}>{doc.name}</div>
                            <div style={{ fontSize: "0.75rem", color: "var(--text-muted)" }}>
                              Status:{" "}
                              {doc.status === "pending"
                                ? "⏳ Belum Diunggah"
                                : doc.status === "blur"
                                ? "🚨 Terdeteksi Blur / Buram"
                                : doc.status === "ocr_extracted"
                                ? "⚡ AI OCR Berhasil Diekstrak"
                                : doc.status === "bypass_manual"
                                ? "🔓 Bypass Manual"
                                : "✅ Diunggah"}
                            </div>
                          </div>
                          <div>
                            {doc.status !== "pending" ? (
                              <span
                                style={{
                                  color:
                                    doc.status === "blur" ? "var(--danger)" : "var(--success)",
                                  fontWeight: "600",
                                  fontSize: "0.85rem",
                                }}
                              >
                                {doc.status === "blur" ? "❌ Buram" : "✓ OK"}
                              </span>
                            ) : (
                              <span style={{ color: "var(--text-muted)", fontSize: "0.8rem" }}>
                                Menunggu
                              </span>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Side-by-Side OCR Editor */}
                  {detailData.financial_data && detailData.financial_data.length > 0 && (
                    <div className="glass-panel">
                      <h3
                        style={{
                          borderBottom: "1px solid var(--border-color)",
                          paddingBottom: "10px",
                          marginBottom: "15px",
                        }}
                      >
                        Verifikasi Human-in-the-Loop OCR
                      </h3>

                      {detailData.prospect.has_blur_document && !detailData.prospect.bypass_manual ? (
                        <div className="alert alert-warning" style={{ margin: "0" }}>
                          Dokumen Laporan Keuangan terdeteksi buram. Harap lakukan re-upload atau
                          Bypass Manual terlebih dahulu.
                        </div>
                      ) : (
                        <div style={{ display: "flex", flexDirection: "column", gap: "20px" }}>
                          <p style={{ fontSize: "0.85rem", color: "var(--text-secondary)" }}>
                            Bandingkan preview PDF asli (kiri) dengan data OCR terstruktur (kanan).
                            Koreksi angka bila diperlukan, lalu simpan.
                          </p>
                          <div className="side-by-side">
                            {/* Left: Mock PDF */}
                            <div className="pdf-viewer-sim">
                              <div
                                style={{
                                  width: "100%",
                                  textAlign: "left",
                                  fontSize: "0.8rem",
                                  fontFamily: "monospace",
                                }}
                              >
                                <div
                                  style={{
                                    borderBottom: "1.5px solid var(--text-muted)",
                                    paddingBottom: "4px",
                                    marginBottom: "8px",
                                    textAlign: "center",
                                    fontWeight: "bold",
                                  }}
                                >
                                  LAPORAN POSISI KEUANGAN ({detailData.prospect.company_name})
                                </div>
                                {ocrRows.map((row) => (
                                  <div
                                    key={row.year}
                                    style={{
                                      marginBottom: "12px",
                                      borderBottom: "1px dashed rgba(255,255,255,0.05)",
                                      paddingBottom: "6px",
                                    }}
                                  >
                                    <div
                                      style={{ color: "var(--accent-blue)", fontWeight: "bold" }}
                                    >
                                      TAHUN FISKAL: {row.year}
                                    </div>
                                    <div>Revenue: {row.revenue.toLocaleString("id-ID")}</div>
                                    <div>Net Profit: {row.net_profit.toLocaleString("id-ID")}</div>
                                    <div>Total Assets: {row.total_assets.toLocaleString("id-ID")}</div>
                                    <div>
                                      Liabilities: {row.total_liabilities.toLocaleString("id-ID")}
                                    </div>
                                    <div>Equity: {row.equity.toLocaleString("id-ID")}</div>
                                    <div>
                                      Cash Flow: {row.operating_cash_flow.toLocaleString("id-ID")}
                                    </div>
                                  </div>
                                ))}
                              </div>
                            </div>

                            {/* Right: Editable OCR */}
                            <div className="ocr-editor-table">
                              <div style={{ overflowX: "auto" }}>
                                <table style={{ marginTop: "0" }}>
                                  <thead>
                                    <tr>
                                      <th>Variabel Keuangan</th>
                                      {ocrRows.map((row) => (
                                        <th key={row.year} style={{ textAlign: "center" }}>
                                          {row.year}
                                        </th>
                                      ))}
                                    </tr>
                                  </thead>
                                  <tbody>
                                    {[
                                      { label: "Revenue", key: "revenue" },
                                      { label: "Net Profit", key: "net_profit" },
                                      { label: "Total Assets", key: "total_assets" },
                                      { label: "Liabilities", key: "total_liabilities" },
                                      { label: "Equity", key: "equity" },
                                      { label: "Aset Lancar", key: "current_assets" },
                                      { label: "Liabilitas Lancar", key: "current_liabilities" },
                                      { label: "Arus Kas Operasional", key: "operating_cash_flow" },
                                      { label: "Piutang Usaha", key: "accounts_receivable" },
                                    ].map((item) => (
                                      <tr key={item.key}>
                                        <td style={{ fontSize: "0.8rem", padding: "6px" }}>
                                          {item.label}
                                        </td>
                                        {ocrRows.map((row, idx) => (
                                          <td key={row.year} style={{ padding: "4px" }}>
                                            <input
                                              type="number"
                                              className="input-control"
                                              style={{
                                                padding: "6px 8px",
                                                fontSize: "0.8rem",
                                                textAlign: "right",
                                                backgroundColor: "#0b0f19",
                                              }}
                                              value={row[item.key]}
                                              onChange={(e) =>
                                                handleOcrCellChange(idx, item.key, e.target.value)
                                              }
                                            />
                                          </td>
                                        ))}
                                      </tr>
                                    ))}
                                  </tbody>
                                </table>
                              </div>
                              <button
                                onClick={handleSaveOcr}
                                className="btn btn-primary"
                                style={{
                                  width: "100%",
                                  padding: "10px",
                                  fontSize: "0.85rem",
                                  marginTop: "15px",
                                }}
                                disabled={actionLoading}
                              >
                                💾 Simpan & Verifikasi Koreksi Data
                              </button>
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default AnalisDashboard;

