import React, { useContext, useState } from "react";
import { AuthProvider, AuthContext } from "./context/AuthContext";
import Login from "./views/Login";
import CommonDashboard from "./views/CommonDashboard";
import MarketingDashboard from "./views/MarketingDashboard";
import AnalisDashboard from "./views/AnalisDashboard";
import AdminDashboard from "./views/AdminDashboard";

// Role-based default landing views
const ROLE_DEFAULT_VIEW = {
  marketing: "daftar",
  analis: "analis",
  komite: "daftar",
  admin: "daftar",
};

function AppContent() {
  const { user, loading } = useContext(AuthContext);
  const [activeView, setActiveView] = useState(null); // null = use role default

  if (loading) {
    return (
      <div
        style={{
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          minHeight: "100vh",
          backgroundColor: "var(--bg-primary)",
        }}
      >
        <p>Memuat Sistem Skoring AI Underwriting...</p>
      </div>
    );
  }

  if (!user) {
    return <Login />;
  }

  // Determine effective active view: explicit selection overrides role default
  const effectiveView = activeView ?? ROLE_DEFAULT_VIEW[user.role] ?? "daftar";

  const renderActiveView = () => {
    switch (effectiveView) {
      // Marketing-only: form submit pengajuan baru
      case "tambah":
        if (user.role === "marketing" || user.role === "admin") {
          return <MarketingDashboard setActiveView={setActiveView} />;
        }
        // Fallback: unauthorized roles see their own default
        return renderFallback();

      // Analyst-specific dashboard
      case "analis":
        if (user.role === "analis" || user.role === "admin") {
          return <AnalisDashboard />;
        }
        return renderFallback();

      // Admin panel
      case "admin":
        if (user.role === "admin") {
          return <AdminDashboard />;
        }
        return renderFallback();

      // Default: shared prospect list & detail (marketing, komite, admin)
      case "daftar":
      default:
        return <CommonDashboard setActiveView={setActiveView} />;
    }
  };

  const renderFallback = () => <CommonDashboard setActiveView={setActiveView} />;

  // ── Sidebar navigation items per role ──
  const sidebarItems = [
    // Analis: primary view is their dedicated dashboard
    ...(user.role === "analis"
      ? [
          {
            view: "analis",
            icon: "🔍",
            label: "Dasbor Analis",
          },
        ]
      : []),

    // Marketing, Komite, Admin: shared prospect list
    ...(["marketing", "komite", "admin"].includes(user.role)
      ? [
          {
            view: "daftar",
            icon: "📊",
            label: "Dasbor Skoring",
          },
        ]
      : []),

    // Marketing + Admin: form tambah prospek
    ...(["marketing", "admin"].includes(user.role)
      ? [
          {
            view: "tambah",
            icon: "📝",
            label: "Buat Pengajuan",
          },
        ]
      : []),

    // Admin only: parameter & audit
    ...(user.role === "admin"
      ? [
          {
            view: "admin",
            icon: "🛠️",
            label: "Parameter & Audit",
          },
        ]
      : []),
  ];

  return (
    <div className="layout-container">
      {/* ── Sidebar ── */}
      <div className="sidebar">
        <div className="sidebar-brand">
          <span style={{ fontSize: "1.5rem" }}>🤖</span>
          <h3>UNDERWRITE AI</h3>
        </div>

        <ul className="sidebar-menu">
          {sidebarItems.map((item) => (
            <li key={item.view}>
              <div
                onClick={() => setActiveView(item.view)}
                className={`sidebar-link ${effectiveView === item.view ? "active" : ""}`}
              >
                <span>{item.icon}</span> {item.label}
              </div>
            </li>
          ))}
        </ul>

        {/* Role badge at bottom of sidebar */}
        <div
          style={{
            marginTop: "auto",
            borderTop: "1px solid var(--border-color)",
            paddingTop: "15px",
          }}
        >
          <div
            style={{
              fontSize: "0.8rem",
              color: "var(--text-muted)",
              marginBottom: "4px",
            }}
          >
            Masuk sebagai:
          </div>
          <div
            style={{
              fontSize: "0.85rem",
              fontWeight: "700",
              color: "var(--text-secondary)",
              textTransform: "capitalize",
            }}
          >
            {user.full_name}
          </div>
          <div
            style={{
              display: "inline-block",
              marginTop: "4px",
              fontSize: "0.7rem",
              padding: "2px 8px",
              borderRadius: "20px",
              background:
                user.role === "admin"
                  ? "rgba(139,92,246,0.2)"
                  : user.role === "analis"
                  ? "rgba(59,130,246,0.2)"
                  : user.role === "komite"
                  ? "rgba(245,158,11,0.2)"
                  : "rgba(34,197,94,0.2)",
              color:
                user.role === "admin"
                  ? "var(--accent-purple)"
                  : user.role === "analis"
                  ? "var(--accent-blue)"
                  : user.role === "komite"
                  ? "var(--warning)"
                  : "var(--success)",
              fontWeight: "700",
              textTransform: "uppercase",
              letterSpacing: "0.5px",
            }}
          >
            {user.role}
          </div>
          <div
            style={{
              fontSize: "0.7rem",
              color: "var(--text-muted)",
              marginTop: "8px",
            }}
          >
            Sistem Skoring v1.0
            <br />
            On-Premise Offline Mode
          </div>
        </div>
      </div>

      {/* ── Main Panel ── */}
      <div className="main-content">{renderActiveView()}</div>
    </div>
  );
}

function App() {
  return (
    <AuthProvider>
      <AppContent />
    </AuthProvider>
  );
}

export default App;

