const renderActiveView = () => {
  switch (effectiveView) {
    // Marketing-only: form submit pengajuan baru
    case "tambah":
      if (user.role === "marketing" || user.role === "admin") {
        return <MarketingDashboard setActiveView={setActiveView} />;
      }
      // Unauthorized role → redirect to their own dashboard
      return renderFallback();

    // Analyst-specific dashboard
    case "analis":
      if (user.role === "analis" || user.role === "admin") {
        return <AnalisDashboard />;
      }
      return renderFallback();

    // Admin panel
    case "admin":
      if (user.role === "admin") {
        return <AdminDashboard />;
      }
      return renderFallback();

    // Default / daftar: shared prospect list
