      if (user.role === "analis") {
        return <AnalisDashboard />;
      }
      return <CommonDashboard setActiveView={setActiveView} />;
  }
};

// Fallback: each role sees their natural home screen
const renderFallback = () => {
  if (user.role === "analis") return <AnalisDashboard />;
  return <CommonDashboard setActiveView={setActiveView} />;
};

